package com.pratik.imagetap;
import org.opencv.core.*;import org.opencv.imgproc.Imgproc;import java.util.*;import java.util.concurrent.atomic.*;
public class ParallelScanTest {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 static Mat template(int i){Mat t=new Mat(32,48,CvType.CV_8UC4,new Scalar(40+i,60,80,255));Imgproc.putText(t,""+i,new Point(2,24),Imgproc.FONT_HERSHEY_SIMPLEX,.65,new Scalar(240,230,210,255),2);return t;}
 public static void main(String[] args){nu.pattern.OpenCV.loadLocally();Core.setNumThreads(1);List<Mat> templates=new ArrayList<>();List<ScanEngine.Job> jobs=new ArrayList<>();Mat screen=new Mat(1280,720,CvType.CV_8UC4,new Scalar(15,25,35,255));AtomicInteger loads=new AtomicInteger();
 for(int i=0;i<51;i++){final Mat t=template(i);templates.add(t);int x=20+i%9*75,y=40+i/9*100;Mat patch=screen.submat(y,y+32,x,x+48);t.copyTo(patch);patch.release();jobs.add(new ScanEngine.Job("image-"+i,1,null,()->{loads.incrementAndGet();return t.clone();},null));}
 VisionMatcher.Hit[] reference=null;for(int n:new int[]{1,2,4})try(ScanEngine engine=new ScanEngine(n)){ScanEngine.Result r=engine.scan(screen,jobs,96,Collections.emptyList(),true,false,()->false,v->{});for(boolean c:r.checked)check(c,"Every target must finish");if(reference==null)reference=r.hits;else for(int i=0;i<51;i++){check((reference[i]==null)==(r.hits[i]==null),"Parallel parity "+i);if(reference[i]!=null)check(reference[i].x==r.hits[i].x&&reference[i].y==r.hits[i].y&&Math.abs(reference[i].score-r.hits[i].score)<.001,"Same best match "+i);}
 int loaded=loads.get();long[] times=new long[5];for(int k=0;k<times.length;k++)times[k]=engine.scan(screen,jobs,96,Collections.emptyList(),true,false,()->false,v->{}).millis;Arrays.sort(times);check(loads.get()==loaded,"Prepared image loaders reused across scans");System.out.println(n+" workers, 51 unique targets warm median ms="+times[2]);List<ScanEngine.Job> tracked=new ArrayList<>();for(int i=0;i<51;i++){ScanEngine.Job j=jobs.get(i);tracked.add(new ScanEngine.Job(j.key,j.scale,j.area,j.loader,r.hits[i]));}ScanEngine.Result recent=engine.scan(screen,tracked,96,Collections.emptyList(),true,false,()->false,v->{});System.out.println(n+" workers tracked scan ms="+recent.millis);for(int i=0;i<51;i++)check((recent.hits[i]==null)==(r.hits[i]==null),"Tracked scan parity");}
 try(ScanEngine engine=new ScanEngine(2)){List<ScanEngine.Job> repeated=new ArrayList<>();for(int i=0;i<51;i++)repeated.add(jobs.get(0));ScanEngine.Result r=engine.scan(screen,repeated,96,Collections.emptyList(),true,false,()->false,v->{});check(r.unique==1,"Identical jobs share one search");check(r.hits[0]!=null,"Found shared target");for(int i=0;i<51;i++)check(r.hits[i]==r.hits[0]&&r.checked[i],"Result fans out to each action");System.out.println("51 duplicate targets unique searches="+r.unique+", ms="+r.millis);
 ScanEngine.Job limited=new ScanEngine.Job(jobs.get(0).key,1,new RegionRules.Region(.8f,.8f,1,1,96),jobs.get(0).loader,null);r=engine.scan(screen,Arrays.asList(jobs.get(0),limited),96,Collections.emptyList(),true,false,()->false,v->{});check(r.unique==2&&r.hits[0]!=null&&r.hits[1]==null,"Different regions must not merge");
 r=engine.scan(screen,jobs,96,Collections.emptyList(),true,false,()->true,v->{});for(boolean c:r.checked)check(!c,"Cancelled work not marked complete");
 AtomicBoolean cancel=new AtomicBoolean();r=engine.scan(screen,jobs,96,Collections.emptyList(),true,false,cancel::get,count->{if(count>=8)cancel.set(true);});int visited=0;for(boolean c:r.checked)if(c)visited++;check(visited<jobs.size(),"Mid-scan cancellation stops the batch");
 boolean failed=false;try{engine.scan(screen,Arrays.asList(jobs.get(0),new ScanEngine.Job("bad",1,null,()->{throw new IllegalStateException("failure");},null)),96,Collections.emptyList(),true,false,()->false,v->{});}catch(IllegalStateException e){failed=true;}check(failed,"Worker error propagated after joining tasks");check(engine.scan(screen,Arrays.asList(jobs.get(0)),96,Collections.emptyList(),true,false,()->false,v->{}).hits[0]!=null,"Engine remains usable after failed batch");}
 // Even if every scan is cancelled after its first target, all targets get a first turn.
 try(ScanEngine engine=new ScanEngine(1);ScanEngine reverseEngine=new ScanEngine(1)){
  List<ScanEngine.Job> reversed=new ArrayList<>(jobs);Collections.reverse(reversed);Set<String> firsts=new HashSet<>();
  for(int turn=0;turn<jobs.size();turn++){AtomicBoolean cancel=new AtomicBoolean();ScanEngine.Result r=engine.scan(screen,jobs,96,Collections.emptyList(),true,false,cancel::get,v->cancel.set(true));int first=-1;for(int i=0;i<r.checked.length;i++)if(r.checked[i]){check(first==-1,"Only one search before cancellation");first=i;}check(first>=0,"A target was checked");firsts.add(jobs.get(first).key);
   cancel.set(false);ScanEngine.Result rr=reverseEngine.scan(screen,reversed,96,Collections.emptyList(),true,false,cancel::get,v->cancel.set(true));for(int i=0;i<rr.checked.length;i++)if(rr.checked[i])check(reversed.get(i).key.equals(jobs.get(first).key),"Display reorder cannot change scan priority");
  }check(firsts.size()==51,"All 51 targets become first across cancelled scans");
 }
 Mat tiny=new Mat(8,8,CvType.CV_8UC4);byte[] noise=new byte[8*8*4];new java.util.Random(81).nextBytes(noise);for(int i=3;i<noise.length;i+=4)noise[i]=(byte)255;tiny.put(0,0,noise);Mat large=new Mat(1920,1080,CvType.CV_8UC4,new Scalar(15,25,35,255));Mat patch=large.submat(600,608,500,508);tiny.copyTo(patch);patch.release();
 try(ScanEngine engine=new ScanEngine(2)){ScanEngine.Result r=engine.scan(large,Arrays.asList(new ScanEngine.Job("tiny",1,null,()->tiny.clone(),null)),100,Collections.emptyList(),true,false,()->false,v->{});check(r.hits[0]!=null&&r.hits[0].x==500&&r.hits[0].y==600,"Tiny target keeps full-resolution matching");}large.release();tiny.release();
 screen.release();for(Mat t:templates)t.release();System.out.println("PASS parallel parity, coverage, cache reuse, exact dedup, independent regions, cancellation and failure recovery");
 }
}
